CREATE OR REPLACE FUNCTION public.math_claim_evaluation(uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e public.math_evaluations;u uuid;
begin
 select ar.student_id into u from public.math_evaluations er join public.math_attempts ar on ar.id=er.attempt_id where er.id=$1;
 perform math_private.require_active(array[u]);perform math_private.lock_evaluation($1);
 select * into e from public.math_evaluations where id=$1;
 if e.state<>'REQUESTED' then raise invalid_parameter_value using message='EVALUATION_NOT_CLAIMABLE';end if;
 update public.math_evaluations set state='PROCESSING',lease_token=gen_random_uuid(),lease_until=clock_timestamp()+interval '5 minutes' where id=e.id returning * into e;
 return jsonb_build_object('evaluation_id',e.id,'lease_token',e.lease_token,'lease_until',e.lease_until,'attempt_id',e.attempt_id,'profile_id',e.profile_id,'selected_extraction_id',e.selected_extraction_id,'authority_solutions',e.authority_solutions);
end$function$

CREATE OR REPLACE FUNCTION public.math_claim_extraction(uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a public.math_attempts;r public.math_extraction_runs;
begin
 select * into a from public.math_attempts where id=$1;
 perform math_private.require_active(array[a.student_id]);perform 1 from public.math_attempts where id=a.id for update;
 if exists(select 1 from public.math_evaluations where attempt_id=a.id) then raise invalid_parameter_value using message='INPUT_FROZEN';end if;
 if a.input_kind='TYPED' or not exists(select 1 from public.math_attempt_artifacts where attempt_id=a.id) or exists(select 1 from public.math_attempt_artifacts where attempt_id=a.id and storage_state<>'PRESENT') then raise invalid_parameter_value using message='INPUT_NOT_READY';end if;
 update public.math_extraction_runs set state='FAILED',error_code='TIMEOUT' where attempt_id=a.id and state='PROCESSING' and lease_until<=clock_timestamp();
 if exists(select 1 from public.math_extraction_runs where attempt_id=a.id and state='PROCESSING') then raise unique_violation using message='EXTRACTION_IN_PROGRESS';end if;
 insert into public.math_extraction_runs(attempt_id,kind,state,lease_token,lease_until) values(a.id,'CANDIDATE','PROCESSING',gen_random_uuid(),clock_timestamp()+interval '5 minutes') returning * into r;
 return jsonb_build_object('run_id',r.id,'lease_token',r.lease_token,'lease_until',r.lease_until,'artifacts',(select jsonb_agg(jsonb_build_object('artifact_id',id,'position',position,'media_type',media_type) order by position) from public.math_attempt_artifacts where attempt_id=a.id));
end$function$

CREATE OR REPLACE FUNCTION public.math_evaluation(p_request jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v jsonb=p_request->'payload';action text=p_request->>'action';reply jsonb;allowed text[];
begin
 if p_request is null or jsonb_typeof(p_request)<>'object' or octet_length(p_request::text)>600000 or p_request-array['dto_version','action','payload']<>'{}' or p_request->>'dto_version' is distinct from 'math-worker-v1' or jsonb_typeof(v) is distinct from 'object' then raise invalid_parameter_value;end if;
 allowed=case action when 'claim' then array['evaluation_id'] when 'finalize' then array['evaluation_id','lease_token','output','learning_judgement'] when 'fail' then array['evaluation_id','lease_token','error_code'] else null end;
 if allowed is null or v-allowed<>'{}' then raise invalid_parameter_value;end if;
 case action
 when 'claim' then
  reply=public.math_claim_evaluation((v->>'evaluation_id')::uuid);
  select reply||jsonb_build_object('context',jsonb_build_object(
   'attempt',jsonb_build_object('attempt_id',a.id,'kind',a.kind,'typed_answer',a.typed_answer,'input_kind',a.input_kind,'prior_evaluation_id',a.prior_evaluation_id,'target_step_id',a.target_step_id),
   'leaf',(select to_jsonb(l) from public.math_subproblems l where id=e.leaf_id),
   'problem',(select to_jsonb(p) from public.math_problems p join public.math_subproblems l on l.problem_id=p.id where l.id=e.leaf_id),
   'profile',(select to_jsonb(p) from public.math_evaluation_profiles p where id=e.profile_id),
   'extraction',(select coalesce(jsonb_agg(to_jsonb(z)-array['attempt_id','run_id'] order by reading_order),'[]') from public.math_extraction_regions z where run_id=e.selected_extraction_id),
   'criteria',(select coalesce(jsonb_agg(to_jsonb(c) order by c.id),'[]') from public.math_evaluation_criteria x join public.math_scoring_criteria c on c.id=x.criterion_id where x.evaluation_id=e.id),
   'sources',(select coalesce(jsonb_agg(to_jsonb(s) order by s.id),'[]') from public.math_evaluation_sources x join public.math_source_artifacts s on s.id=x.source_id where x.evaluation_id=e.id),
   'solutions',(select coalesce(jsonb_agg(to_jsonb(s) order by s.id),'[]') from public.math_canonical_solutions s where e.authority_solutions ? s.id::text)
  )) into reply from public.math_evaluations e join public.math_attempts a on a.id=e.attempt_id where e.id=(v->>'evaluation_id')::uuid;if reply->'context' is not null then
 reply=jsonb_set(reply,'{context}',(reply->'context')||math_private.hanyang_worker_references(reply->'context'));
end if;

 when 'finalize' then if v ? 'learning_judgement' then
 begin
 reply=to_jsonb(math_private.q3_finalize_with_learning((v->>'evaluation_id')::uuid,(v->>'lease_token')::uuid,v->'output',v->'learning_judgement'));
 exception when invalid_parameter_value then
 if sqlerrm not in ('LEARNING_INVALID','LEARNING_CRITERIA_MISMATCH','LEARNING_OBSERVATION_MISMATCH') then raise;end if;
 reply=to_jsonb(public.math_finalize_evaluation((v->>'evaluation_id')::uuid,(v->>'lease_token')::uuid,v->'output'));
 end;
 else reply=to_jsonb(public.math_finalize_evaluation((v->>'evaluation_id')::uuid,(v->>'lease_token')::uuid,v->'output')); end if;
 when 'fail' then perform public.math_fail_evaluation((v->>'evaluation_id')::uuid,(v->>'lease_token')::uuid,v->>'error_code');reply=jsonb_build_object('failed',true);
 end case;
 if octet_length(reply::text)>2097152 then raise program_limit_exceeded using message='MATH_RESPONSE_BOUND';end if;
 return jsonb_build_object('dto_version','math-worker-v1','action',action,'result',reply);
end$function$

CREATE OR REPLACE FUNCTION public.math_extraction(p_request jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v jsonb=p_request->'payload'; action text=p_request->>'action';result jsonb;allowed text[];
begin
 if p_request is null or jsonb_typeof(p_request)<>'object' or octet_length(p_request::text)>300000 or p_request-array['dto_version','action','payload']<>'{}' or p_request->>'dto_version' is distinct from 'math-extraction-v1' or jsonb_typeof(v) is distinct from 'object' then raise invalid_parameter_value;end if;
 allowed=case action when 'claim' then array['attempt_id'] when 'finalize' then array['run_id','lease_token','output'] when 'fail' then array['run_id','lease_token','error_code'] else null end;
 if allowed is null or v-allowed<>'{}' then raise invalid_parameter_value;end if;
 case action
 when 'claim' then
  result=public.math_claim_extraction((v->>'attempt_id')::uuid);
  result=result||jsonb_build_object('evidence',(select jsonb_agg(jsonb_build_object('artifact_id',id,'bucket',bucket,'object_key',object_key,'media_type',media_type,'content_sha256',content_sha256,'byte_size',byte_size,'position',position) order by position) from public.math_attempt_artifacts where attempt_id=(v->>'attempt_id')::uuid));
 when 'finalize' then result=jsonb_build_object('run_id',public.math_finalize_extraction((v->>'run_id')::uuid,(v->>'lease_token')::uuid,v->'output'));
 when 'fail' then perform public.math_fail_extraction((v->>'run_id')::uuid,(v->>'lease_token')::uuid,v->>'error_code');result=jsonb_build_object('failed',true);
 end case;
 if octet_length(result::text)>2097152 then raise program_limit_exceeded using message='MATH_RESPONSE_BOUND';end if;
 return jsonb_build_object('dto_version','math-extraction-v1','action',action,'result',result);
end$function$

CREATE OR REPLACE FUNCTION public.math_request_evaluation(uuid, uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a public.math_attempts;e public.math_evaluations;p uuid;run uuid;h text;solution_pins jsonb;
begin
 select * into a from public.math_attempts where id=$1;
 if a.student_id is distinct from math_private.current_subject() then raise insufficient_privilege;end if;
 perform math_private.require_active(array[a.student_id]);perform math_private.lock_account_attempt(a.id);
 if $2 is null then raise invalid_parameter_value;end if;
 h=encode(sha256(convert_to(a.id::text,'UTF8')),'hex');
 select * into e from public.math_evaluations where idempotency_key=$2;
 if found then if e.attempt_id<>a.id or e.request_sha256<>h then raise unique_violation;end if;return e.id;end if;
 if exists(select 1 from public.math_evaluations where attempt_id=a.id and state in ('REQUESTED','PROCESSING','COMPLETED')) then raise unique_violation using message='ATTEMPT_ALREADY_EVALUATED';end if;
 if a.input_kind<>'TYPED' then
  select x.id into run from public.math_extraction_runs x where x.attempt_id=a.id and x.kind='CONFIRMED' and x.state='COMPLETED' and x.predecessor_id=(select id from public.math_extraction_runs where attempt_id=a.id and kind='CANDIDATE' order by created_at desc,id desc limit 1);
  if run is null or exists(select 1 from public.math_attempt_artifacts where attempt_id=a.id and storage_state<>'PRESENT') then raise invalid_parameter_value using message='INPUT_NOT_READY';end if;
 end if;
 p=math_private.resolve_profile(a.leaf_id);
 select coalesce(jsonb_agg(id order by id),'[]') into solution_pins from public.math_canonical_solutions where leaf_id=a.leaf_id and state='ACTIVE';
 insert into public.math_evaluations(attempt_id,leaf_id,profile_id,selected_extraction_id,request_kind,idempotency_key,request_sha256,state,authority_solutions)
 values(a.id,a.leaf_id,p,run,case when a.kind='INITIAL' then 'MATH_INITIAL_EVALUATION' else 'MATH_REEVALUATION' end,$2,h,'REQUESTED',solution_pins) returning * into e;
 insert into public.math_evaluation_sources(evaluation_id,source_id) select e.id,s.id from public.math_source_artifacts s join public.math_subproblems l on l.problem_id=s.problem_id where l.id=a.leaf_id;
 insert into public.math_evaluation_criteria(evaluation_id,leaf_id,criterion_id) select e.id,a.leaf_id,id from public.math_scoring_criteria where leaf_id=a.leaf_id;
 perform math_private.authorize_billing(e.id);return e.id;
end$function$

CREATE OR REPLACE FUNCTION public.math_session_continue(p_exam uuid, p_key uuid, p_attempts uuid[], p_previous uuid, p_expected_credits integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid=auth.uid(); account uuid; previous math_private.session_runs; existing math_private.session_runs; ids uuid[]; quote jsonb; result uuid;
begin
 perform math_private.require_active(array[u]);
 select id into account from public.credit_accounts where user_id=u for update;
 if account is null then raise insufficient_privilege;end if;
 if p_expected_credits is null or p_expected_credits not in (0,1) or p_key is null or p_exam is null or coalesce(cardinality(p_attempts),0) not between 1 and 100 then raise invalid_parameter_value;end if;
 select array_agg(x order by x) into ids from unnest(p_attempts) x;
 select * into existing from math_private.session_runs where student_id=u and request_key=p_key;
 if found then
  if existing.exam_id<>p_exam or existing.attempt_ids<>ids or existing.previous_run_id is distinct from p_previous
   or (select credits_required from public.essay_billing_decisions where id=existing.decision_id)<>p_expected_credits then raise unique_violation using message='SESSION_REPLAY_CONFLICT';end if;
  return existing.id;
 end if;
 if p_previous is null then
  if p_expected_credits<>1 then raise invalid_parameter_value using message='CHARGE_CHANGED';end if;
  result=public.math_session_submit(p_exam,p_key,p_attempts,null);
  update math_private.session_runs set submission_index=1 where id=result;
  return result;
 end if;
 select * into previous from math_private.session_runs where id=p_previous and student_id=u for update;
 if not found or previous.exam_id<>p_exam then raise insufficient_privilege;end if;
 if exists(select 1 from math_private.session_runs where previous_run_id=previous.id and state<>'cancelled') then raise unique_violation using message='ROUND_ALREADY_CONTINUED';end if;
 quote=public.math_session_quote(previous.id);
 if (quote->>'credits_required')::integer<>p_expected_credits then raise invalid_parameter_value using message='CHARGE_CHANGED';end if;
 if (select array_agg(leaf_id order by leaf_id) from public.math_attempts where id=any(ids) and student_id=u) is distinct from (select array_agg(leaf_id order by leaf_id) from math_private.session_members where run_id=previous.id) then raise invalid_parameter_value using message='FROZEN_QUESTION_SET';end if;
 if exists(select 1 from public.math_attempts child where child.id=any(ids) and not exists(
  select 1 from math_private.session_members pm join math_private.session_evaluations x on x.attempt_id=pm.attempt_id join public.math_evaluations e on e.id=x.evaluation_id
  where pm.run_id=previous.id and pm.leaf_id=child.leaf_id and child.predecessor_id=pm.attempt_id and child.prior_evaluation_id=e.id and e.state='COMPLETED')) then raise invalid_parameter_value using message='INVALID_REWRITE_SOURCE';end if;
 result=public.math_session_submit(p_exam,p_key,p_attempts,(quote->>'included_parent_id')::uuid);
 update math_private.session_runs set previous_run_id=previous.id,submission_index=(quote->>'submission_index')::integer where id=result;
 return result;
end$function$

CREATE OR REPLACE FUNCTION public.math_session_continue_source(p_exam uuid, p_key uuid, p_attempts uuid[], p_previous uuid, p_expected_credits integer, p_expected_grant uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare account uuid; existing uuid; source jsonb; run uuid; actual uuid; grant_count integer;
begin
 perform math_private.require_active(array[auth.uid()]);
 if p_expected_credits is null or p_expected_credits not in(0,1) or p_key is null or p_exam is null
  or (p_expected_credits=0 and p_expected_grant is not null) then raise invalid_parameter_value using message='EXPECTED_CREDIT_SOURCE_REQUIRED';end if;
 select id into account from public.credit_accounts where user_id=auth.uid() for update;
 if account is null then raise insufficient_privilege;end if;
 select id into existing from math_private.session_runs where student_id=auth.uid() and request_key=p_key;
 if existing is null and p_expected_credits=1 then
  if p_expected_grant is null then raise invalid_parameter_value using message='EXPECTED_CREDIT_SOURCE_REQUIRED';end if;
  source=essay_beta_private.credit_source(account,p_exam);
  if source->>'grant_id' is distinct from p_expected_grant::text then raise invalid_parameter_value using message='CHARGE_SOURCE_CHANGED';end if;
 end if;
 run=public.math_session_continue(p_exam,p_key,p_attempts,p_previous,p_expected_credits);
 select count(distinct t.grant_id),(array_agg(distinct t.grant_id))[1] into grant_count,actual from math_private.session_runs r
 join public.credit_transactions t on t.decision_id=r.decision_id and t.transaction_type='reserve' where r.id=run;
 if (p_expected_credits=1 and (grant_count<>1 or (p_expected_grant is not null and actual is distinct from p_expected_grant))) or (p_expected_credits=0 and grant_count<>0) then
  raise invalid_parameter_value using message='CHARGE_SOURCE_CHANGED';end if;
 return run;
end$function$

CREATE OR REPLACE FUNCTION public.math_session_read(p_run uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare answer jsonb; r math_private.session_runs; quote jsonb;
begin
 answer=public.math_session_read_before_task16g(p_run);
 select * into r from math_private.session_runs where id=p_run and student_id=auth.uid();
 if not found then raise insufficient_privilege;end if;
 if r.state='completed' then quote=public.math_session_quote(r.id);end if;
 return answer||jsonb_build_object('previous_run_id',r.previous_run_id,'submission_index',coalesce(r.submission_index,case when r.parent_id is null then 1 else 2 end),'continuous_cycles_supported',true,'next_quote',quote,
 'free_rewrite_available',coalesce((quote->>'credits_required')::integer=0,false),'credits_required',(select credits_required from public.essay_billing_decisions where id=r.decision_id));
end$function$

CREATE OR REPLACE FUNCTION public.math_session_retry(p_run uuid, p_key uuid)
 RETURNS uuid[]
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r math_private.session_runs; prior math_private.session_retries; item record; ids uuid[]='{}'; eid uuid;
begin
 perform math_private.require_active(array[auth.uid()]);
 select * into r from math_private.session_runs where id=p_run and student_id=auth.uid();
 if r.id is null or p_key is null then raise insufficient_privilege;end if;
 perform 1 from public.credit_accounts where id=r.account_id for update;
 select * into r from math_private.session_runs where id=p_run for update;
 select * into prior from math_private.session_retries where run_id=p_run and request_key=p_key;
 if found then return prior.evaluation_ids;end if;
 if r.state<>'reserved' then raise invalid_parameter_value;end if;
 for item in select m.attempt_id,latest.state from math_private.session_members m left join lateral (
   select e.state from math_private.session_evaluations x join public.math_evaluations e on e.id=x.evaluation_id where x.attempt_id=m.attempt_id order by x.generation desc limit 1
  ) latest on true where m.run_id=p_run order by m.attempt_id loop
  if item.state is null or item.state not in ('COMPLETED','FAILED') then raise invalid_parameter_value using message='RECONCILIATION_REQUIRED';end if;
  if item.state='FAILED' then
   eid=public.math_request_evaluation(item.attempt_id,gen_random_uuid());ids=array_append(ids,eid);
  end if;
 end loop;
 if cardinality(ids)=0 then raise invalid_parameter_value using message='NO_FAILED_QUESTIONS';end if;
 insert into math_private.session_retries values(p_run,p_key,ids);
 return ids;
end$function$

CREATE OR REPLACE FUNCTION public.math_session_submit(p_exam uuid, p_key uuid, p_attempts uuid[], p_parent uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid=auth.uid(); account uuid; r math_private.session_runs; parent math_private.session_runs;
 a public.math_attempts; ids uuid[]; leaves uuid[]; parent_leaves uuid[]; selected_grant uuid;
 rid uuid=gen_random_uuid(); did uuid=gen_random_uuid(); aid uuid; evaluation uuid; catalog jsonb;
begin
 perform math_private.require_active(array[u]);
 select id into account from public.credit_accounts where user_id=u for update;
 if account is null then raise insufficient_privilege;end if;
 if p_key is null or p_exam is null or coalesce(cardinality(p_attempts),0) not between 1 and 100 or array_position(p_attempts,null) is not null then raise invalid_parameter_value;end if;
 select array_agg(v order by v) into ids from unnest(p_attempts) v;
 if cardinality(ids)<>(select count(distinct v) from unnest(ids) v) then raise invalid_parameter_value;end if;
 select * into r from math_private.session_runs where student_id=u and request_key=p_key;
 if found then
  if r.exam_id<>p_exam or r.attempt_ids<>ids or r.parent_id is distinct from p_parent then raise unique_violation using message='SESSION_REPLAY_CONFLICT';end if;
  return r.id;
 end if;
 catalog=math_private.release_catalog(p_exam);
 foreach aid in array ids loop
  select * into a from public.math_attempts where id=aid and student_id=u for update;
  if a.id is null or exists(select 1 from public.math_evaluations where attempt_id=aid) or exists(select 1 from math_private.session_members where attempt_id=aid) then raise invalid_parameter_value using message='SESSION_INPUT_UNAVAILABLE';end if;
  if (select count(*) from jsonb_array_elements(catalog) x where x->>'leaf_id'=a.leaf_id::text and x->>'essay_exam_id'=p_exam::text and exists(select 1 from public.essay_questions q where q.id=(x->>'essay_question_id')::uuid and q.essay_exam_id=p_exam))<>1 then raise invalid_parameter_value using message='QUESTION_NOT_RELEASED';end if;
  if not exists(select 1 from public.math_subproblems l join public.math_problems p on p.id=l.problem_id join public.math_problem_sets s on s.id=p.problem_set_id where l.id=a.leaf_id and s.essay_exam_id=p_exam and p.state='ACTIVE' and s.state='ACTIVE') then raise invalid_parameter_value using message='QUESTION_NOT_IN_EXAM';end if;
 end loop;
 select array_agg(leaf_id order by leaf_id) into leaves from public.math_attempts where id=any(ids);
 if cardinality(leaves)<>(select count(distinct v) from unnest(leaves) v) then raise invalid_parameter_value;end if;
 if p_parent is not null then
  select * into parent from math_private.session_runs where id=p_parent and student_id=u for update;
  if parent.id is null or parent.exam_id<>p_exam or parent.parent_id is not null or parent.state<>'completed' or clock_timestamp()>=math_private.cycle_deadline(parent.decision_id,parent.completed_at)
    or exists(select 1 from math_private.session_runs where parent_id=parent.id)
    or exists(select 1 from public.credit_transactions where decision_id=parent.decision_id and transaction_type='refund') then raise invalid_parameter_value using message='REEVALUATION_NOT_INCLUDED';end if;
  select array_agg(leaf_id order by leaf_id) into parent_leaves from math_private.session_members where run_id=parent.id;
  if leaves<>parent_leaves then raise invalid_parameter_value using message='FROZEN_QUESTION_SET';end if;
  if exists(select 1 from public.math_attempts child where child.id=any(ids) and not exists(
    select 1 from math_private.session_members pm join math_private.session_evaluations x on x.attempt_id=pm.attempt_id join public.math_evaluations pe on pe.id=x.evaluation_id
    where pm.run_id=parent.id and pm.leaf_id=child.leaf_id and child.predecessor_id=pm.attempt_id and child.prior_evaluation_id=pe.id and pe.state='COMPLETED')) then raise invalid_parameter_value using message='INVALID_REWRITE_SOURCE';end if;
 else
  selected_grant=(essay_beta_private.credit_source(account,p_exam)->>'grant_id')::uuid;
  if selected_grant is not null then perform 1 from public.credit_grants where id=selected_grant and account_id=account for update;end if;
  if selected_grant is null then raise sqlstate 'PT402' using message='INSUFFICIENT_CREDIT';end if;
 end if;
 insert into public.essay_billing_decisions(id,account_id,idempotency_key,policy_key,policy_version,reason,credits_required,status,included_by_decision_id)
 values(did,account,rid,'essay-exam-cycle','math-session-v1',case when p_parent is null then 'paid_cycle' else 'included_revision' end,case when p_parent is null then 1 else 0 end,'authorized',parent.decision_id);
 insert into math_private.session_runs(id,student_id,account_id,exam_id,request_key,parent_id,decision_id,attempt_ids) values(rid,u,account,p_exam,p_key,p_parent,did,ids);
 if selected_grant is not null then
  insert into public.credit_transactions(account_id,grant_id,decision_id,transaction_type,balance_delta,reserved_delta,idempotency_key,reason_code)
  values(account,selected_grant,did,'reserve',0,1,'math-session:'||rid||':reserve','essay_exam_initial');
  update public.essay_billing_decisions set status='reserved',reserved_at=clock_timestamp() where id=did;
 end if;
 insert into math_private.session_members select rid,ar.id,ar.leaf_id,(x->>'essay_question_id')::uuid from public.math_attempts ar join jsonb_array_elements(catalog) x on x->>'leaf_id'=ar.leaf_id::text where ar.id=any(ids);
